// Flatten every page of accounts and split them into batches for the bulk endpoints.
const cfg = $('Set Bounce Alert Thresholds').first().json;

const seen = new Set();
const accounts = [];
for (const page of $input.all()) {
  for (const a of (page.json.items || [])) {
    if (a.email && !seen.has(a.email)) {
      seen.add(a.email);
      accounts.push({
        email: a.email,
        status: a.status,
        warmupStatus: a.warmup_status,
        dailyLimit: a.daily_limit,
        warmupScore: a.stat_warmup_score ?? null,
      });
    }
  }
}

const size = Math.min(100, Math.max(1, Number(cfg.batchSize) || 50));
const batches = [];
for (let i = 0; i < accounts.length; i += size) {
  const chunk = accounts.slice(i, i + size);
  batches.push({ json: { emails: chunk.map((a) => a.email), accounts: chunk } });
}
return batches; // no accounts = nothing to check, workflow stops here

// Combine bounce stats, warmup health and DNS checks into one verdict per account.
const cfg = $('Set Bounce Alert Thresholds').first().json;
const num = (v, d) => (Number.isFinite(Number(v)) ? Number(v) : d);
const maxBounce = num(cfg.maxBounceRatePct, 3);
const minSent = num(cfg.minSentForBounceCheck, 30);
const pauseScore = num(cfg.pauseBelowWarmupScore, 75);
const warnScore = num(cfg.warnBelowWarmupScore, 90);

const accounts = $('Package Account Batches').all().flatMap((i) => i.json.accounts || []);

// Warmup health per email
const warm = {};
for (const i of $('Post Warmup Health Check').all()) Object.assign(warm, (i.json && i.json.aggregate_data) || {});

// DNS results per sending domain
const dns = {};
for (const i of $('Post DNS Records Check').all()) {
  const j = i.json || {};
  for (const d of j.success_list || []) dns[d.domain] = { ...d, allPass: true };
  for (const d of j.failure_list || []) dns[d.domain] = d;
}

// Bounce stats per email over the lookback window
const rows = $('Fetch Bounce Stats').all().flatMap((i) => {
  const j = i.json || {};
  if (Array.isArray(j.result)) return j.result;
  return j.email_account ? [j] : [];
});
const stats = {};
for (const r of rows) {
  const s = (stats[r.email_account] = stats[r.email_account] || { sent: 0, bounced: 0 });
  s.sent += Number(r.sent) || 0;
  s.bounced += Number(r.bounced) || 0;
}

const STATUS = { 1: 'Active', 2: 'Paused', '-1': 'Connection error', '-2': 'Soft bounce error', '-3': 'Sending error' };

return accounts.map((a) => {
  const issues = [];
  let verdict = 'healthy';
  const raise = (level) => {
    if (level === 'pause' || (level === 'warn' && verdict === 'healthy')) verdict = level;
  };

  // 1. Bounce rate
  const s = stats[a.email] || { sent: 0, bounced: 0 };
  const bounceRate = s.sent ? Number(((s.bounced / s.sent) * 100).toFixed(2)) : 0;
  if (s.sent >= minSent && bounceRate > maxBounce) {
    issues.push(`Bounce rate ${bounceRate}% (${s.bounced}/${s.sent} in ${cfg.lookbackDays}d)`);
    raise('pause');
  } else if (s.sent >= minSent && bounceRate > maxBounce / 2) {
    issues.push(`Bounce rate rising: ${bounceRate}%`);
    raise('warn');
  }

  // 2. Warmup health and spam placement
  const w = warm[a.email];
  const health = w && typeof w.health_score === 'number' ? w.health_score : a.warmupScore;
  const spamPct = w && w.sent ? Number((((w.landed_spam || 0) / w.sent) * 100).toFixed(1)) : null;
  if (typeof health === 'number') {
    if (health < pauseScore) { issues.push(`Warmup health ${health}%`); raise('pause'); }
    else if (health < warnScore) { issues.push(`Warmup health dropped to ${health}%`); raise('warn'); }
  }

  // 3. Domain DNS (MX, SPF, DKIM, DMARC)
  const domain = a.email.split('@')[1];
  const d = dns[domain];
  const failing = d ? ['mx', 'spf', 'dkim', 'dmarc'].filter((k) => d[k] === false) : [];
  if (failing.length) {
    issues.push(`DNS failing: ${failing.join(', ').toUpperCase()}`);
    raise(cfg.pauseOnDnsFailure === true ? 'pause' : 'warn');
  }

  // 4. Account and warmup status reported by Instantly
  if (a.status < 0) { issues.push(STATUS[String(a.status)] || `Error status ${a.status}`); raise('warn'); }
  if (a.warmupStatus !== 1) { issues.push('Warmup is not running'); raise('warn'); }

  const isActive = a.status === 1;
  if (a.status === 2 && verdict === 'healthy') verdict = 'paused';
  const willPause = verdict === 'pause' && cfg.autoPause === true && isActive;

  return {
    json: {
      email: a.email,
      domain,
      accountStatus: STATUS[String(a.status)] || String(a.status),
      sent: s.sent,
      bounced: s.bounced,
      bounceRatePct: bounceRate,
      warmupHealth: typeof health === 'number' ? health : null,
      spamPct,
      dns: d ? (failing.length ? `Failing: ${failing.join(', ').toUpperCase()}` : 'Pass') : 'Not checked',
      verdict,
      willPause,
      action: willPause ? 'Auto-paused' : verdict === 'pause' ? (isActive ? 'Pause recommended' : 'Already paused or inactive') : verdict === 'warn' ? 'Watch' : verdict === 'paused' ? 'Already paused' : 'None',
      issues,
    },
  };
});

