// Build one Slack summary for the whole workspace.
const cfg = $('Set Bounce Alert Thresholds').first().json;
const all = $input.all().map((i) => i.json);
const paused = all.filter((a) => a.willPause);
const recommend = all.filter((a) => a.verdict === 'pause' && !a.willPause);
const warn = all.filter((a) => a.verdict === 'warn');
const healthy = all.filter((a) => a.verdict === 'healthy');
const alreadyPaused = all.filter((a) => a.verdict === 'paused');

if (!paused.length && !recommend.length && !warn.length && cfg.notifyWhenAllHealthy !== true) return [];

const line = (a) => `• \`${a.email}\`: ${a.issues.join('; ')}`;
const section = (title, list) => (list.length ? `\n*${title} (${list.length})*\n${list.slice(0, 25).map(line).join('\n')}${list.length > 25 ? `\n…and ${list.length - 25} more` : ''}` : '');

const header = paused.length || recommend.length ? ':rotating_light:' : warn.length ? ':warning:' : ':white_check_mark:';
const text = [
  `${header} *Instantly deliverability check: ${$now.toFormat('yyyy-MM-dd')}*`,
  `Checked ${all.length} accounts | Healthy ${healthy.length} | Watch ${warn.length} | Auto-paused ${paused.length} | Pause recommended ${recommend.length} | Already paused ${alreadyPaused.length}`,
  section('Auto-paused', paused),
  section('Pause recommended (auto-pause is off or account not active)', recommend),
  section('Watch', warn),
  !paused.length && !recommend.length && !warn.length ? '\nAll sending accounts look healthy.' : '',
].filter(Boolean).join('\n');

return [{ json: { text } }];
